import json
R=C=28
palette=[1,3,5,7,9]  # indexed by (r+c) mod 5
out=[]
for r in range(R):
    if r<2:
        row=[1]*C
    elif r==2:
        row=[1,1]+[4]*(C-2)
    else:
        row=[1,1,4]+[palette[(r+c)%5] for c in range(3,C)]
        # Seed irregularities at the upper-left corner of the periodic field.
        if r==3:
            row[3:6]=[3,2,1]
        elif r==4:
            row[3]=2
        elif r==5:
            row[3]=1
    out.append(row)
assert len(out)==28 and all(len(row)==28 for row in out)
assert all(0 <= v <= 9 for row in out for v in row)
print(json.dumps(out, separators=(',',':')))

