pal=[1,3,5,7,9]
out=[]
for r in range(28):
    if r<2:
        row=[1]*28
    elif r==2:
        row=[1,1]+[4]*26
    else:
        row=[1,1,4]+[pal[(r+c)%5] for c in range(3,28)]
        special={(3,3):3,(3,4):2,(3,5):1,(4,3):2,(5,3):1}
        for (rr,cc),v in special.items():
            if rr==r: row[cc]=v
    out.append(row)
assert len(out)==28 and all(len(row)==28 for row in out)
assert all(type(v)==int and 0<=v<=9 for row in out for v in row)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

